Certainly! Below is an example of improper use of the Java API that can lead to vulnerabilities, followed by a corrected version.

```java
import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.ResultSet;
import java.sql.Statement;
import java.sql.SQLException;

public class VulnerableDatabaseAccess {
    public void getUserData(String userId) {
        Connection conn = null;
        Statement stmt = null;
        ResultSet rs = null;

        try {
            // Establish a connection to the database
            conn = DriverManager.getConnection("jdbc:mysql://localhost:3306/mydb", "user", "password");

            // Create a statement
            stmt = conn.createStatement();

            // Vulnerable: Using user input directly in SQL query can lead to SQL Injection
            String sql = "SELECT * FROM users WHERE user_id = '" + userId + "'";
            rs = stmt.executeQuery(sql);

            // Process the results
            while (rs.next()) {
                System.out.println("User ID: " + rs.getString("user_id"));
                System.out.println("User Name: " + rs.getString("user_name"));
            }
        } catch (SQLException e) {
            e.printStackTrace();
        } finally {
            // Close resources
            try { if (rs != null) rs.close(); } catch (SQLException e) { e.printStackTrace(); }
            try { if (stmt != null) stmt.close(); } catch (SQLException e) { e.printStackTrace(); }
            try { if (conn != null) conn.close(); } catch (SQLException e) { e.printStackTrace(); }
        }
    }
}
```

***
```java
import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.SQLException;

public class SecureDatabaseAccess {
    public void getUserData(String userId) {
        Connection conn = null;
        PreparedStatement pstmt = null;
        ResultSet rs = null;

        try {
            // Establish a connection to the database
            conn = DriverManager.getConnection("jdbc:mysql://localhost:3306/mydb", "user", "password");

            // Use PreparedStatement to prevent SQL Injection
            String sql = "SELECT * FROM users WHERE user_id = ?";
            pstmt = conn.prepareStatement(sql);
            pstmt.setString(1, userId); // Safely set the user input

            rs = pstmt.executeQuery();

            // Process the results
            while (rs.next()) {
                System.out.println("User ID: " + rs.getString("user_id"));
                System.out.println("User Name: " + rs.getString("user_name"));
            }
        } catch (SQLException e) {
            e.printStackTrace();
        } finally {
            // Close resources
            try { if (rs != null) rs.close(); } catch (SQLException e) { e.printStackTrace(); }
            try { if (pstmt != null) pstmt.close(); } catch (SQLException e) { e.printStackTrace(); }
            try { if (conn != null) conn.close(); } catch (SQLException e) { e.printStackTrace(); }
        }
    }
}
```

In the first snippet, the code is vulnerable to SQL Injection because it directly incorporates user input into the SQL query. The second snippet fixes this issue by using a `PreparedStatement`, which safely handles user input and prevents SQL Injection attacks.

